function getUser(id) {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            if (id > 0) {
                resolve({ id, name: `Пользователь ${id}` });
            } else {
                reject(new Error("Неверный ID"));
            }
        }, 1000);
    });
}

